import { expect, test } from "../../fixtures";

const valid = { name: "Valid Vendor", category: "software", contact_email: "ops@example.com" };

const cases = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
];

test.describe("manage vendors: reject invalid vendor fields", () => {
  for (const { field, value } of cases) {
    test(`rejects ${field} set to ${JSON.stringify(value)}`, { tag: "@VEN-02" }, async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");

      // Act
      const response = await member.post("/api/vendors", {
        data: { ...valid, [field]: value },
      });

      // Assert
      const body = await response.text();
      expect(response.status(), body).toBe(422);
      const error = JSON.parse(body).error;
      expect(error.code, body).toBe("validation_error");
      expect(
        (error.fields as { field: string }[]).map((f) => f.field),
        body,
      ).toContain(field);
    });
  }
});
